        if(!buf){ fprintf(stderr,"  %.0f MB: allocation failed, stopping the sweep\n",
                          SIZES_MB[si]); break; }
        // touch every page so the timed pass measures reads and not first-touch faults
        for(size_t i=0;i<n;i++) buf[i] = (uint64_t)i*2654435761u;

